// A canvas of cards on `createCanvas`: the pointer gestures, the arrow keys, the marquee, the snapping and the live region are
// the primitive's. The skin adds the two things a canvas needs once it is bigger than its frame — a minimap that is also a
// camera, and a drag that pans when it reaches the edge — both of which are policies over `panBy` and `screenToWorld`, so
// neither of them is a member of the primitive.
import {
  type CanvasNodeInput,
  createCanvas,
  type Canvas as CanvasController,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createMemo, For, onCleanup, Show } from "solid-js";

import { t } from "./theme.ts" with { type: "cssints" };

export type { CanvasNodeInput };

export interface CanvasProps {
  /** The cards, in world units: whole px, the origin at the top left of the world. */
  readonly nodes: ReadonlyArray<CanvasNodeInput>;
  /** The canvas's accessible name. */
  readonly label: string;
  /** The frame's size, screen px (default 720 x 460). */
  readonly width?: number | undefined;
  readonly height?: number | undefined;
  /** Off leaves the drag alone at the edge; on (default) a drag near the edge pans. */
  readonly autoPan?: boolean | undefined;
  readonly class?: string | undefined;
}

const DEFAULT_WIDTH = 720;
const DEFAULT_HEIGHT = 460;
/** How far from the frame's edge a drag starts panning, and how many pixels a move pans there. */
const AUTO_PAN_MARGIN = 48;
const AUTO_PAN_STEP = 12;
/** One wheel notch, as the primitive's fixed point (4096 = x1). */
const ZOOM_STEP = 1.15 * 4096;
const MINIMAP_WIDTH = 168;
const MINIMAP_HEIGHT = 112;
/** Room around the extents on the minimap, in world units. */
const MINIMAP_PAD = 80;

const rootClass = css.cn(css.display("grid"), css.gap(t.space._2), css.width("100%"));

// The frame clips the world; the primitive's own style carries `overflow: clip` and `touch-action: none`, which is why the
// host's style is merged in rather than replaced.
const viewportClass = css.cn(
  css.position("relative"),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.md),
  css.overflow("clip"),
  css.touchAction("none"),
  css.bg(t.color.page),
  // a dot grid that does not move with the camera: the camera's own transform is the only motion
  css.backgroundImage("radial-gradient(circle, rgb(0 0 0 / 0.14) 1px, transparent 1px)"),
  css.backgroundSize("24px 24px"),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
);

const cardClass = css.cn(
  css.position("absolute"),
  css.display("flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.padding(t.space._2),
  css.boxSizing("border-box"),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.md),
  css.bg(t.color.surface),
  css.color(t.color.text),
  css.fontSize(t.font.sizeSm),
  css.fontWeight("500"),
  css.textAlign("center"),
  css.cursor("grab"),
  css.boxShadow("0 1px 2px rgb(0 0 0 / 0.12)"),
  css.attr("aria-selected", "true")(
    css.borderColor(t.color.highlight),
    css.boxShadow("inset 0 0 0 2px", t.color.highlight),
  ),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
);

const minimapClass = css.cn(
  css.position("absolute"),
  css.right(t.space._2),
  css.bottom(t.space._2),
  css.bg(t.color.surface),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.sm),
  css.boxShadow("0 1px 3px rgb(0 0 0 / 0.16)"),
  css.cursor("pointer"),
  css.opacity("0.94"),
  css.hover(css.opacity("1")),
);

const minimapNodeClass = css.cn(css.fill(t.color.border), css.stroke("none"));

const minimapViewClass = css.cn(
  css.fill("transparent"),
  css.stroke(t.color.highlight),
  css.strokeWidth("1.5"),
);

const statusClass = css.cn(css.margin("0"), css.fontSize(t.font.sizeSm), css.color(t.color.muted));

/** How far into an edge margin a coordinate is: -1 at the near edge, 1 at the far one, 0 in the middle. */
const depth = (at: number, size: number): number => {
  if (at < AUTO_PAN_MARGIN) {
    return -Math.min(1, (AUTO_PAN_MARGIN - at) / AUTO_PAN_MARGIN);
  }
  if (at > size - AUTO_PAN_MARGIN) {
    return Math.min(1, (at - (size - AUTO_PAN_MARGIN)) / AUTO_PAN_MARGIN);
  }
  return 0;
};

/**
 * The minimap: every card as a box, the frame's own view as a rectangle, and a click anywhere on it centres the camera
 * there. Its scale is the union of the cards and the current view, so the rectangle is always on the map; it is
 * `aria-hidden`, because it is a second way to the same camera the viewport already offers from the keyboard.
 */
const Minimap = (props: {
  readonly canvas: CanvasController;
  readonly nodes: ReadonlyArray<CanvasNodeInput>;
}): JSX.Element => {
  // the camera, read through the primitive: a pan or a zoom re-derives both boxes
  const view = createMemo(() => {
    const { viewport } = props.canvas.state();
    const topLeft = props.canvas.screenToWorld({ x: 0, y: 0 });
    const bottomRight = props.canvas.screenToWorld({ x: viewport.width, y: viewport.height });
    return {
      x: topLeft.x,
      y: topLeft.y,
      width: bottomRight.x - topLeft.x,
      height: bottomRight.y - topLeft.y,
    };
  });
  const world = createMemo(() => {
    const cards = props.nodes.reduce(
      (box, node) => ({
        left: Math.min(box.left, node.x),
        top: Math.min(box.top, node.y),
        right: Math.max(box.right, node.x + node.width),
        bottom: Math.max(box.bottom, node.y + node.height),
      }),
      { left: 0, top: 0, right: 0, bottom: 0 },
    );
    const here = view();
    const left = Math.min(cards.left, here.x) - MINIMAP_PAD;
    const top = Math.min(cards.top, here.y) - MINIMAP_PAD;
    const right = Math.max(cards.right, here.x + here.width) + MINIMAP_PAD;
    const bottom = Math.max(cards.bottom, here.y + here.height) + MINIMAP_PAD;
    return { left, top, width: Math.max(1, right - left), height: Math.max(1, bottom - top) };
  });
  const scale = createMemo(() =>
    Math.min(MINIMAP_WIDTH / world().width, MINIMAP_HEIGHT / world().height),
  );
  const at = (x: number, y: number): { readonly x: number; readonly y: number } => ({
    x: (x - world().left) * scale(),
    y: (y - world().top) * scale(),
  });
  const jump = (event: PointerEvent): void => {
    // the map is inside the frame: a click on it must not also start a pan or a marquee underneath
    event.stopPropagation();
    const box = (event.currentTarget as Element).getBoundingClientRect();
    const point = at(0, 0);
    const x = world().left + (event.clientX - box.left - point.x) / scale();
    const y = world().top + (event.clientY - box.top - point.y) / scale();
    props.canvas.animateTo({ kind: "centre", x, y });
  };
  return (
    <svg
      data-part="canvas-minimap"
      aria-hidden="true"
      class={minimapClass}
      width={MINIMAP_WIDTH}
      height={MINIMAP_HEIGHT}
      viewBox={`0 0 ${MINIMAP_WIDTH} ${MINIMAP_HEIGHT}`}
      onPointerDown={jump}
    >
      <For each={props.nodes}>
        {(node) => (
          <rect
            data-part="canvas-minimap-node"
            data-node={node.id}
            class={minimapNodeClass}
            x={at(node.x, node.y).x}
            y={at(node.x, node.y).y}
            width={Math.max(2, node.width * scale())}
            height={Math.max(2, node.height * scale())}
            rx="1"
          />
        )}
      </For>
      <rect
        data-part="canvas-minimap-view"
        class={minimapViewClass}
        x={at(view().x, view().y).x}
        y={at(view().x, view().y).y}
        width={Math.max(2, view().width * scale())}
        height={Math.max(2, view().height * scale())}
      />
    </svg>
  );
};

/**
 * A canvas of cards: drag one to move it (the pointer's own snap), marquee the empty space, Tab in and out, the arrows move
 * the selected card, `+` / `-` zoom. The minimap in the corner is the second camera and a click on it recentres; a drag that
 * reaches the frame's edge pulls the camera with it, so a card can be carried past what is on screen.
 */
export const Canvas = (props: CanvasProps): JSX.Element => {
  let frame: HTMLElement | undefined;
  // the frame loop of an auto-pan, and the pointer it is panning about (the last one the drag reported)
  let raf: number | undefined;
  let held: { readonly x: number; readonly y: number } | undefined;
  const canvas = createCanvas({
    nodes: props.nodes,
    label: props.label,
    viewport: {
      width: props.width ?? DEFAULT_WIDTH,
      height: props.height ?? DEFAULT_HEIGHT,
    },
  });

  /** Stop pulling, and forget the pointer: a release, a cancel, an unmount, or a drag that ended. */
  const stopPanning = (): void => {
    held = undefined;
    if (raf !== undefined) {
      cancelAnimationFrame(raf);
      raf = undefined;
    }
  };

  /**
   * One frame of the pull: pan by how deep the pointer is in the margin, then ask for another frame while it is still
   * there. `panBy` re-derives the drag against the new camera (the primitive's own `derive`), so the dragged card stays
   * under the pointer and the world slides beneath it — that re-derivation is why a *held* pointer can keep panning at all.
   */
  const pull = (): void => {
    raf = undefined;
    const at = held;
    if (at === undefined || frame === undefined || canvas.state().mode !== "dragging") {
      stopPanning();
      return;
    }
    const box = frame.getBoundingClientRect();
    const dx = depth(at.x - box.left, box.width) * AUTO_PAN_STEP;
    const dy = depth(at.y - box.top, box.height) * AUTO_PAN_STEP;
    if (dx === 0 && dy === 0) {
      // out of the margin: the drag carries on, the camera does not
      return;
    }
    const before = canvas.peek().camera;
    canvas.panBy(dx, dy);
    // the world's own edge: pulling further moves nothing, so the loop stops instead of spinning
    const after = canvas.peek().camera;
    if (after.tx === before.tx && after.ty === before.ty) {
      return;
    }
    raf = requestAnimationFrame(pull);
  };

  // Auto-pan is a policy, not a member: the primitive draws a drag from the pointer's world position and `panBy` re-derives
  // it, so pulling the camera under a pointer in the edge margin is the whole of it. A move arms the loop; the loop itself
  // keeps going while the pointer rests there, which is what a drag past the edge is for.
  const autoPan = (event: PointerEvent): void => {
    if (props.autoPan === false) {
      return;
    }
    // the mode is read by the frame, not here: the primitive's writes land on the microtask flush, so a move that starts
    // the drag still reads the mode before it (and a move with no drag arms one frame that decides and stops)
    held = { x: event.clientX, y: event.clientY };
    if (raf === undefined) {
      raf = requestAnimationFrame(pull);
    }
  };

  onCleanup(stopPanning);

  const wheel = (event: WheelEvent): void => {
    const box = frame?.getBoundingClientRect();
    if (box === undefined) {
      return;
    }
    event.preventDefault();
    canvas.zoomBy(event.deltaY < 0 ? ZOOM_STEP : 1 / ZOOM_STEP, [
      event.clientX - box.left,
      event.clientY - box.top,
    ]);
  };

  return (
    <div data-part="canvas" class={css.cn(rootClass, props.class)}>
      <div
        {...canvas.viewportProps}
        ref={(element) => {
          frame = element;
          canvas.viewportProps.ref(element);
        }}
        onPointerMove={(event) => {
          canvas.viewportProps.onPointerMove(event);
          autoPan(event);
        }}
        onPointerUp={(event) => {
          canvas.viewportProps.onPointerUp(event);
          stopPanning();
        }}
        onPointerCancel={(event) => {
          canvas.viewportProps.onPointerCancel(event);
          stopPanning();
        }}
        onLostPointerCapture={(event) => {
          canvas.viewportProps.onLostPointerCapture(event);
          stopPanning();
        }}
        onWheel={wheel}
        data-part="canvas-frame"
        class={viewportClass}
        style={{
          ...canvas.viewportProps.style,
          width: `${props.width ?? DEFAULT_WIDTH}px`,
          height: `${props.height ?? DEFAULT_HEIGHT}px`,
        }}
      >
        <div {...canvas.layerProps} data-part="canvas-layer">
          <For each={canvas.nodeIds()}>
            {(id) => {
              const node = props.nodes.find((candidate) => candidate.id === id);
              return (
                <div
                  {...canvas.nodeProps(id)}
                  data-part="canvas-card"
                  data-node={id}
                  class={cardClass}
                  style={canvas.nodeProps(id).style}
                >
                  {/* the shell is the tab stop and always rendered; the body drops when the primitive culls it */}
                  <Show when={!canvas.isCulled(id)}>{node?.label}</Show>
                </div>
              );
            }}
          </For>
        </div>
        <Minimap canvas={canvas} nodes={props.nodes} />
      </div>
      <p {...canvas.liveRegionProps} data-part="canvas-status" class={statusClass} />
    </div>
  );
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

// The canvas starter's check: the two things the skin adds to the primitive — a minimap that is also a camera, and a drag
// that pans at the frame's edge — plus the wiring a host must not get wrong (the frame's own style, the cards' tab stop and
// the live region). The pointer events are real `PointerEvent`s on the frame, the same path a user's mouse takes.
import { render } from "@solidjs/web";
import { afterEach, describe, expect, it } from "vite-plus/test";

import { Canvas, type CanvasNodeInput } from "./canvas.tsx";

const CARDS: ReadonlyArray<CanvasNodeInput> = [
  { id: "a", label: "Alpha", x: 40, y: 40, width: 200, height: 90 },
  { id: "b", label: "Beta", x: 360, y: 40, width: 200, height: 90 },
  { id: "c", label: "Gamma", x: 900, y: 260, width: 200, height: 90 },
];

const mounted: Array<() => void> = [];

afterEach(() => {
  for (const dispose of mounted.splice(0)) {
    dispose();
  }
});

const settle = (): Promise<void> =>
  new Promise((resolve) => {
    requestAnimationFrame(() => requestAnimationFrame(() => resolve(undefined)));
  });

const frames = (): Promise<void> =>
  new Promise((resolve) => {
    requestAnimationFrame(() => requestAnimationFrame(() => resolve()));
  });

const mount = (props: { readonly width?: number; readonly height?: number } = {}): HTMLElement => {
  const host = document.createElement("div");
  document.body.append(host);
  const dispose = render(
    () => (
      <Canvas
        nodes={CARDS}
        label="Release board"
        width={props.width ?? 720}
        height={props.height ?? 460}
      />
    ),
    host,
  );
  mounted.push(() => {
    dispose();
    host.remove();
  });
  return host;
};

const part = <T extends Element>(host: ParentNode, name: string): T => {
  const element = host.querySelector<T>(`[data-part="${name}"]`);
  if (element === null) {
    throw new Error(`canvas: no ${name}`);
  }
  return element;
};

/** The camera as the primitive renders it: the layer's own custom properties. */
const camera = (
  host: ParentNode,
): { readonly x: number; readonly y: number; readonly zoom: number } => {
  const style = getComputedStyle(part<HTMLElement>(host, "canvas-layer"));
  return {
    x: Number(style.getPropertyValue("--canvas-x")),
    y: Number(style.getPropertyValue("--canvas-y")),
    zoom: Number(style.getPropertyValue("--canvas-zoom")),
  };
};

/** A real pointer event on the frame, at a client position. */
const pointer = (target: Element, type: string, clientX: number, clientY: number): void => {
  target.dispatchEvent(
    new PointerEvent(type, {
      bubbles: true,
      cancelable: true,
      composed: true,
      clientX,
      clientY,
      pointerId: 1,
      pointerType: "mouse",
      isPrimary: true,
      button: 0,
    }),
  );
};

describe("Canvas", () => {
  it("renders the cards in the frame, one tab stop and a live region, and the world scrolls under them", () => {
    const host = mount();
    const frame = part<HTMLElement>(host, "canvas-frame");
    const cards = [...host.querySelectorAll<HTMLElement>('[data-part="canvas-card"]')];

    expect(frame.getAttribute("role")).toBe("region");
    expect(frame.getAttribute("aria-label")).toBe("Release board");
    // the primitive's own style survives the skin's: the frame is the clipping box the camera needs
    expect(getComputedStyle(frame).overflow).toBe("clip");
    expect(getComputedStyle(frame).width).toBe("720px");
    expect(cards.map((card) => card.dataset.node)).toEqual(["a", "b", "c"]);
    // Gamma is off screen, so its body is culled: the shell stays, named, and never costs a tab stop
    expect(cards.map((card) => card.textContent)).toEqual(["Alpha", "Beta", ""]);
    expect(cards[2]!.getAttribute("aria-label")).toBe("Gamma");
    // every card is its own tab stop (the canvas is a focusgroup, not one composite), culled or not
    expect(cards.filter((card) => card.tabIndex === 0)).toHaveLength(3);
    expect(part(host, "canvas-status").getAttribute("role")).toBe("status");
  });

  it("draws a minimap of every card and the frame's own view", () => {
    const host = mount();
    const map = part<SVGSVGElement>(host, "canvas-minimap");
    expect(map.getAttribute("aria-hidden")).toBe("true");
    expect(
      [...map.querySelectorAll('[data-part="canvas-minimap-node"]')].map((rect) =>
        rect.getAttribute("data-node"),
      ),
    ).toEqual(["a", "b", "c"]);
    const view = part<SVGRectElement>(host, "canvas-minimap-view");
    // the frame is 720 x 460 of a wider world, so the view rectangle is smaller than the map
    expect(Number(view.getAttribute("width"))).toBeGreaterThan(0);
    expect(Number(view.getAttribute("width"))).toBeLessThan(168);
  });

  it("centres the camera on a click on the minimap", async () => {
    const host = mount();
    const before = camera(host);
    const map = part<SVGSVGElement>(host, "canvas-minimap");
    const box = map.getBoundingClientRect();
    // the far corner of the map: the card that is out of the frame
    pointer(map, "pointerdown", box.right - 6, box.bottom - 6);
    await settle();
    // the camera tweens to its goal, so the frame needs a few of them
    for (let i = 0; i < 40; i += 1) {
      await frames();
    }
    const after = camera(host);
    expect(after.x).toBeLessThan(before.x);
    expect(after.y).toBeLessThanOrEqual(before.y);
  });

  it("pans when a drag reaches the frame's edge, and stays put in the middle", async () => {
    const host = mount();
    const frame = part<HTMLElement>(host, "canvas-frame");
    const box = frame.getBoundingClientRect();
    const card = part<HTMLElement>(host, "canvas-card");
    const start = card.getBoundingClientRect();

    // a drag that stays in the middle of the frame does not move the camera
    pointer(frame, "pointerdown", start.left + 20, start.top + 20);
    pointer(frame, "pointermove", start.left + 60, start.top + 40);
    await settle();
    const middle = camera(host);

    // …and one that reaches the right edge pulls it: the world moves under the pointer
    pointer(frame, "pointermove", box.right - 4, box.top + 120);
    await settle();
    const edge = camera(host);
    expect(edge.x).not.toBe(middle.x);

    pointer(frame, "pointerup", box.right - 4, box.top + 120);
    await settle();
  });

  it("keeps pulling while the pointer rests at the edge, and stops on release", async () => {
    const host = mount();
    const frame = part<HTMLElement>(host, "canvas-frame");
    const box = frame.getBoundingClientRect();
    const card = part<HTMLElement>(host, "canvas-card");
    const start = card.getBoundingClientRect();

    pointer(frame, "pointerdown", start.left + 20, start.top + 20);
    pointer(frame, "pointermove", box.right - 6, box.top + 160);
    await settle();
    const armed = camera(host).x;

    // no further moves: the loop is what keeps the camera going while the pointer is held in the margin
    for (let i = 0; i < 6; i += 1) {
      await frames();
    }
    const pulled = camera(host).x;
    expect(pulled).not.toBe(armed);

    pointer(frame, "pointerup", box.right - 6, box.top + 160);
    await settle();
    const released = camera(host).x;
    for (let i = 0; i < 6; i += 1) {
      await frames();
    }
    expect(camera(host).x).toBe(released);
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
